 public async Task<IResult> ReconciliationReport(HttpContext h){await security.RequirePermissionAsync(h,"reconciliation.read","Dataset",CommerceStore.Dataset,ct:h.RequestAborted);var report=await store.Transaction(async tx=>{var collectionRows=await tx.Rows("SELECT Id,OrderId,Kind,Collected,Pending,Refunded FROM m0commerce.Collections WHERE Dataset='demo_m0' ORDER BY Id");var operationRows=await tx.Rows("SELECT Id,Body FROM m0commerce.Documents WHERE Dataset='demo_m0' AND Kind='RefundOperation'");var receiptRows=await tx.Rows("SELECT Id,Kind,Body FROM m0commerce.Documents WHERE Dataset='demo_m0' AND Kind IN ('DemoReceipt','ReceiptAdjustment')");var orderRows=await tx.Rows("SELECT Body FROM m0commerce.Documents WHERE Dataset='demo_m0' AND Kind='Order'");var operations=operationRows.Select(x=>JsonNode.Parse((string)x[1])!.AsObject()).ToArray();var collections=collectionRows.Select(x=>new{Id=(string)x[0],OrderId=(string)x[1],Kind=(string)x[2],Collected=(long)x[3],Pending=(long)x[4],Refunded=(long)x[5]}).ToArray();var ids=collections.Select(x=>x.Id).ToHashSet(StringComparer.Ordinal);var findings=new List<JsonObject>();long collected=0,pending=0,refunded=0,available=0,primary=0,lateOrExtra=0;foreach(var c in collections){collected=checked(collected+c.Collected);pending=checked(pending+c.Pending);refunded=checked(refunded+c.Refunded);available=checked(available+c.Collected-c.Pending-c.Refunded);if(c.Kind=="Primary")primary=checked(primary+c.Collected);else lateOrExtra=checked(lateOrExtra+c.Collected);var sourceOps=operations.Where(x=>x.Text("sourceCollectionId")==c.Id).ToArray();var expectedPending=sourceOps.Where(x=>x.Text("state") is "Processing" or "Unknown").Sum(x=>x.Number("amountTwd"));var expectedRefunded=sourceOps.Where(x=>x.Text("state")=="Succeeded").Sum(x=>x.Number("amountTwd"));if(expectedPending!=c.Pending)findings.Add(CommerceWire.Obj(("code","REFUND_PENDING_MISMATCH"),("sourceId",c.Id),("ledgerTwd",c.Pending),("operationsTwd",expectedPending)));if(expectedRefunded!=c.Refunded)findings.Add(CommerceWire.Obj(("code","REFUND_SETTLED_MISMATCH"),("sourceId",c.Id),("ledgerTwd",c.Refunded),("operationsTwd",expectedRefunded)));foreach(var op in sourceOps){var units=op["units"] as JsonArray??[];var itemAmount=units.Sum(x=>x?.AsObject().Number("paidTwd")??0);var calculated=checked(itemAmount+op.Number("shippingTwd"));if(units.Count>0&&calculated!=op.Number("amountTwd"))findings.Add(CommerceWire.Obj(("code","REFUND_AMOUNT_MISMATCH"),("sourceId",c.Id),("operationId",op.Text("id"))));}}foreach(var op in operations.Where(x=>!ids.Contains(x.Text("sourceCollectionId"))))findings.Add(CommerceWire.Obj(("code","REFUND_SOURCE_MISSING"),("operationId",op.Text("id"))));var receiptExceptions=receiptRows.Select(x=>JsonNode.Parse((string)x[2])!.AsObject()).Count(x=>x.Text("state") is "Failed" or "Unknown" or "Processing");return CommerceWire.Obj(("mode","mock"),("readOnly",true),("scheduleStatus","ManualOnly"),("coverage","Current demo_m0 ledger snapshot; no bank, provider or tax authority reconciliation"),("cutoffAt",clock.GetUtcNow()),("state",findings.Count==0?"NoDifferences":"DifferencesFound"),("summary",CommerceWire.Obj(("collectionCount",collections.Length),("primaryCollectedTwd",primary),("lateOrExtraCollectedTwd",lateOrExtra),("collectedTwd",collected),("refundPendingTwd",pending),("refundSucceededTwd",refunded),("availableMockTwd",available),("confirmedOrderCount",orderRows.Count(x=>JsonNode.Parse((string)x[0])!.AsObject().Text("orderState")=="Confirmed")),("refundOperationCount",operations.Length),("receiptExceptionCount",receiptExceptions))),("findings",new JsonArray(findings.Select(x=>(JsonNode?)x).ToArray())));},h.RequestAborted);return M0Http.Json(h,report);}
